func (q *Queries) SearchUnifiedEntities(ctx context.Context, arg SearchUnifiedEntitiesParams) ([]SearchUnifiedEntitiesRow, error) {
	rows, err := q.db.Query(ctx, searchUnifiedEntities,
		arg.Column1,
		arg.Column2,
		arg.Column3,
		arg.Column4,
		arg.Column5,
		arg.Column6,
		arg.Column7,
		arg.Column8,
		arg.Column9,
		arg.Column10,
		arg.Column11,
		arg.Column12,
		arg.Column13,
		arg.Column14,
		arg.Column15,
		arg.Column16,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchUnifiedEntitiesRow{}
	for rows.Next() {
		var i SearchUnifiedEntitiesRow
		if err := rows.Scan(
			&i.Source,
			&i.Kind,
			&i.NativeID,
			&i.CanonicalID,
			&i.ListingID,
			&i.OfferingID,
			&i.Latitude,
			&i.Longitude,
			&i.HousingCompanyID,
			&i.HousingCompanyName,
			&i.LinkStatus,
			&i.LinkMethod,
			&i.LinkScore,
			&i.ExternalUrlAvailable,
			&i.PriceMatchTransactionID,
			&i.PriceMatchScope,
			&i.PriceMatchStatus,
			&i.PriceMatchMethod,
			&i.PriceMatchScore,
			&i.PriceMatchPriceEur,
			&i.InsightCount,
			&i.InsightTopSeverity,
			&i.Headline,
			&i.Address,
			&i.City,
			&i.Postal,
			&i.Price,
			&i.Area,
			&i.RoomLayout,
			&i.Url,
			&i.LastSeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

